import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool shouldPause) public {
        // Initialize the contract so it is in a usable state
        c.initialize(address(this));
        // Set up necessary roles: grant DEFAULT_ADMIN_ROLE to ourselves (address(this)) to call onlyLRTAdmin functions
        bytes32 DEFAULT_ADMIN_ROLE = 0x00;
        // The contract uses IAccessControl(address(lrtConfig)).hasRole(...)
        // Since we are the deployer and initializer, and we control the lrtConfig address (address(this)),
        // we need to ensure hasRole returns true for our calls.
        // However, the contract expects an external call to lrtConfig.hasRole which will revert if lrtConfig is not a contract.
        // We deploy a minimal mock config that returns true for hasRole for DEFAULT_ADMIN_ROLE and MANAGER role.
        // Actually, the initialize function sets lrtConfig to the provided address. We can deploy a mock that returns true.
        // But note: the test imports only from Test.sol and C_under_test.sol. We can define a helper.
        // Wait, the rules say: "You MAY define minimal helper contract(s) ... AFTER InvMutTest only when needed."
        // Since the role check is an external call that must succeed, we need an adversarial counterparty (a real contract that returns true).
        // We'll deploy a minimal RoleResponder helper.
        // But we can also use vm.mockCall? No, that's forbidden.
        // So we define a helper contract after InvMutTest.
        RoleResponder helper = new RoleResponder();
        c.updateLRTConfig(address(helper));
        // Now we have admin role.
        // If shouldPause is true, we call pause(), else we call unpause() (or do nothing extra).
        if (shouldPause) {
            c.pause();
        } else {
            c.unpause();
        }
        // The property: paused() must equal shouldPause (i.e., reflect the actual paused state we attempted to set).
        // In the correct implementation, paused() returns the internal _paused state.
        // In the mutant, paused() always returns false.
        // Thus, for shouldPause = true, the correct returns true, the mutant returns false.
        // For shouldPause = false, both return false.
        // So the assertion that paused() == shouldPause holds for all inputs for the correct, but fails for mutant when shouldPause = true.
        assertTrue(c.paused() == shouldPause);
    }
}

