        // Ensure the admin is not zero address and can call initialize and pause
        vm.assume(admin != address(0));
        // Deploy a minimal LRTConfig that satisfies isSupportedAsset and hasRole checks to bypass access control for initialization
        // Since initialize checks msg.sender and lrtConfig internal setup, we need to deploy a config that is compliant.
        // However, the bug is about paused() returning !_paused. We can test the invariant without initializing the full state
        // by directly calling pause/unpause if we set msg.sender to LRTAdmin or LRTManager. But access control is enforced by
        // the contract itself. To make the test feasible, we deploy a minimal manager that grants the role to admin.
        // (The reference C uses LRTConfigRoleChecker which checks roles on lrtConfig. We need to set up a config that returns true for hasRole)
        // We deploy a helper config contract that always returns true for hasRole.
        LRTConfigHelper config = new LRTConfigHelper();
        // Initialize c with this config
        c.initialize(address(config));
        // Grant Manager role to admin so admin can pause
        config.setRole(LRTConstants.MANAGER, admin, true);
        // Simulate the admin pausing or not pausing
        vm.prank(admin);
        if (shouldPause) {
            c.pause();
        } else {
            // If shouldPause is false, we leave it unpaused. Since initial state is unpaused, nothing to do.
            // But we can still call pause and then unpause to verify the invariant, but we want to test the property after pausing.
            // Actually, to trigger the bug we need the state to be paused. So if shouldPause is true, we pause.
            // If false, we can just check the default state.
        }
        // The invariant: paused() must equal the actual paused state. After pausing, paused() must be true.
        // In the reference version, paused() returns true when paused. In the buggy version, it returns false.
        // So the assertion: if we paused (shouldPause == true), then paused() must be true.
        assertTrue((shouldPause && c.paused()) || (!shouldPause && !c.paused()));
    }
