pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // initialize so the onlyLRTAdmin modifier does not revert
        // We need a simple contract that acts as admin. The admin of DEFAULT_ADMIN_ROLE
        // is the contract itself (or any address that has the role). We can use a helper
        // that grants DEFAULT_ADMIN_ROLE to this test contract.
        // But the constructor of C disables initializers, so we need to call initialize first.
        // However, onlyLRTAdmin checks the role on lrtConfig. Initially lrtConfig is zero address.
        // Calling any function that uses onlyLRTAdmin on an uninitialized config would revert.
        // The test must set up a proper lrtConfig that recognizes the caller as admin.
        // We deploy a minimal LRTConfig that grants DEFAULT_ADMIN_ROLE to this test contract.
        // That requires a helper that implements IAccessControl and ILRTConfig.
        // This is the adversarial environment needed because the bug is about admin-gated access.
        // The bug itself is in updateLRTConfig: it always reverts, regardless of admin.
        // We need the reference to succeed and update lrtConfig, and the buggy to fail.
        // To allow the fuzzer to choose the new config address, we pass it as a parameter.
        // To make the reference succeed, we must set up a minimal lrtConfig that recognizes
        // this test contract as admin. We deploy that helper here.

        // Deployment of minimal admin-aware config
        vm.prank(address(this));
        c.initialize(address(new MinimalLRTConfig()));
    }

    function testFuzz_property(address newConfig) public {
        // The newConfig that we want to set via updateLRTConfig
        // This is the fuzzed input.
        // The function is guarded by onlyLRTAdmin, which requires the caller
        // to have DEFAULT_ADMIN_ROLE on the current lrtConfig.
        // Our setup ensures this test contract has that role on the initial lrtConfig.
        // We call updateLRTConfig as ourselves.

        bool ok;
        try c.updateLRTConfig(newConfig) {
            ok = true;
        } catch {
            ok = false;
        }

        // The property: if the call succeeded (ok == true), then the lrtConfig getter
        // must return the address that was passed. If the call reverted, lrtConfig remains
        // unchanged. But the buggy version always reverts; the reference succeeds for
        // admissible inputs (non-zero newConfig).
        // For a universal property that holds for all inputs on the reference and fails on the buggy:
        // After the call, if ok is true then lrtConfig() must equal newConfig.
        // The reference satisfies this for every fuzzed newConfig (because the call succeeds only when
        // newConfig != address(0), and then lrtConfig is updated).
        // The buggy version never sets ok=true, so the implication is vacuously true for it,
        // but that is not enough to distinguish. We need a property that the reference always satisfies
        // and the buggy does NOT for some input.
        // Instead, we can state: either the call succeeded and lrtConfig() == newConfig,
        // OR the call reverted and lrtConfig() != newConfig.
        // The reference: for every newConfig, if newConfig == address(0) it reverts (due to checkNonZeroAddress),
        // so lrtConfig() stays as the old config (non-zero helper), so lrtConfig() != newConfig holds.
        // For non-zero newConfig, it succeeds and lrtConfig() == newConfig holds.
        // The buggy: always reverts, so lrtConfig() is always the initial address (non-zero helper).
        // For newConfig = address(0), lrtConfig() != newConfig holds (both reference and buggy).
        // For any non-zero newConfig, reference succeeds and equality holds, but buggy reverts
        // and equality does NOT hold (because lrtConfig() remains initial helper, not newConfig).
        // So the property: if the call succeeded then lrtConfig() == newConfig
        // is not enough because buggy never succeeds. We need a property that directly asserts
        // that lrtConfig() differs from newConfig when the call reverts AND newConfig is not the old one.
        // But we cannot know the old one inside the fuzz test without assuming it.
        // Better: We assert that the call succeeded exactly when newConfig is non-zero.
        // Reference: succeeds iff newConfig != 0. Buggy: never succeeds.
        // Property: ok == (newConfig != address(0))
        // This holds for reference for all newConfig; for buggy it fails for any non-zero newConfig.

        bool expectedOk = (newConfig != address(0));
        assertTrue(ok == expectedOk);
    }
}

// Minimal LRTConfig helper that grants DEFAULT_ADMIN_ROLE to this test contract
// so that onlyLRTAdmin passes. This is required to test the admin-gated function.
contract MinimalLRTConfig {
    // IAccessControl minimal: hasRole() returns true for DEFAULT_ADMIN_ROLE and msg.sender == test contract
    // We hardcode the test contract address? No, we cannot. But the test deploys this helper, and
    // the caller during setup is address(this) (InvMutTest). We need the helper to know who deployed it.
    // We store the deployer as the sole admin.
    address public admin;

    constructor() {
        admin = msg.sender;
    }

    function hasRole(bytes32 role, address account) external view returns (bool) {
        bytes32 DEFAULT_ADMIN_ROLE = 0x00;
        if (role == DEFAULT_ADMIN_ROLE && account == admin) {
            return true;
        }
        return false;
    }

    // Other required ILRTConfig functions that might be called, with minimal implementation
    function rsETH() external view returns (address) {
        return address(0);
    }

    function assetStrategy(address) external view returns (address) {
        return address(0);
    }

    function isSupportedAsset(address) external view returns (bool) {
        return false;
    }

    function getLSTToken(bytes32) external view returns (address) {
        return address(0);
    }

    function getContract(bytes32) external view returns (address) {
        return address(0);
    }

    function getSupportedAssetList() external view returns (address[] memory) {
        return new address[](0);
    }

    function depositLimitByAsset(address) external view returns (uint256) {
        return 0;
    }

    // To allow the fuzzer to pass any newConfig, we need the helper to also allow
    // updateLRTConfig to succeed on the reference. The reference updateLRTConfig only
    // checks onlyLRTAdmin and then sets lrtConfig. It doesn't call anything else on the new config.
    // So no additional functions needed.
}

