import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address caller, address newConfig) public {
        // Adversarial counterparty: a minimal contract that implements
        // ILRTConfig/IAccessControl so that the initialization can succeed
        // and `hasRole(DEFAULT_ADMIN_ROLE, caller)` returns false for
        // anyone other than the actual admin.
        AdminHelper helper = new AdminHelper(newConfig);

        // Initialize C (caller is whoever deploys the helper, but init is
        // called by anyone successful – we use an EOA because we already
        // have the admin contract).
        c.initialize(address(helper));

        // caller is an arbitrary EOA (fuzzed), not the default admin.
        vm.assume(caller != address(helper) && caller != address(this));
        vm.assume(newConfig != address(0));

        bool ok = true;
        vm.prank(caller);
        try c.updateLRTConfig(newConfig) {
        } catch {
            ok = false;
        }

        // Rule: A non‑admin caller MUST NOT succeed in updating the LRT config
        // (the correct contract reverts, the buggy one allows it).
        assertTrue(!ok);
    }
}

// Minimal adversarial helper that implements the interfaces needed by C and
// always says "caller is NOT the default admin".
contract AdminHelper {
    address public admin;
    bool public isSupportedAssetReturn = true;

    constructor(address _admin) {
        admin = _admin;
    }

    function hasRole(bytes32 role, address account) external view returns (bool) {
        // Only admin has the default admin role (0x00).
        if (role == 0x00 && account == admin) return true;
        return false;
    }

    function isSupportedAsset(address) external view returns (bool) {
        return isSupportedAssetReturn || true;
    }

    function rsETH() external view returns (address) {
        return address(0xdead);
    }

    function depositLimitByAsset(address) external view returns (uint256) {
        return type(uint256).max;
    }

    function getContract(bytes32) external view returns (address) {
        return address(this);
    }

    // fallback to receive `updateLRTConfig` call pattern
    fallback() external payable {}
